/* xx_mtree_extractor.c - search raw data for MTREE.
 *
 * Scans for:
 *   23 6D 74 72 65 65 at +0  ("#mtree")
 * Offset 0 is always tried as well.
 * Each candidate must be accepted by the mtree reader, which also measures it,
 * and named by the detector, both on a view that starts at the candidate.
 * See xx_format_extractor_engine.h.
 *
 * GENERATED by gen_extractors.py from the detector's prefilters.
 */

#include "../xx_format_extractor_engine.h"
#include "xxfclib/formats/mtree/xx_mtree.h"

static const uint8_t k_anchor0[] = { 0x23, 0x6D, 0x74, 0x72, 0x65, 0x65 };

static const xx_format_search_anchor k_anchors[] = {
    { k_anchor0, sizeof(k_anchor0), 0U },
};

static const xx_file_type_t k_types[] = { XX_FILE_TYPE_MTREE };

static Abstractformat *xx_mtree_search_open(xx_io_device *window) {
    xx_mtree *reader = xx_mtree_create(window, 0);
    return reader ? &reader->format : NULL;
}

static void xx_mtree_search_close(Abstractformat *format) {
    /* The format is the first member, so this is the reader itself. */
    xx_mtree_free((xx_mtree *)format);
}

static const xx_format_search_desc k_desc = {
    k_types, sizeof(k_types) / sizeof(k_types[0]),
    k_anchors, sizeof(k_anchors) / sizeof(k_anchors[0]),
    xx_mtree_search_open, xx_mtree_search_close
};

static xx_format_search_state *xx_mtree_create_format_search(
    xx_format_extractor *self, xx_io_device *device, const xx_list_s *options,
    xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_create(&k_desc, device, options, pd);
}

static const xx_format_search_info *xx_mtree_get_current_format_info(
    xx_format_extractor *self, xx_format_search_state *state) {
    (void)self;
    return xx_format_search_current(state);
}

static bool xx_mtree_format_search_find_next(xx_format_extractor *self,
                                          xx_format_search_state *state,
                                          xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_find_next(state, pd);
}

static void xx_mtree_free_format_search(xx_format_extractor *self,
                                     xx_format_search_state *state) {
    (void)self;
    xx_format_search_free(state);
}

xx_format_extractor xx_mtree_extractor = {
    xx_mtree_create_format_search,
    xx_mtree_get_current_format_info,
    xx_mtree_format_search_find_next,
    xx_mtree_free_format_search
};
